CREATE TABLE "finance_verifications"("id" uuid PRIMARY KEY,"created_at" timestamptz NOT NULL,"updated_at" timestamptz NOT NULL,"organization_id" uuid NOT NULL REFERENCES "organizations"("id"),"verification_no" varchar(64) NOT NULL,"idempotency_key" varchar(128) NOT NULL,"status" varchar NOT NULL DEFAULT 'ACTIVE',"direction" varchar NOT NULL,"settlement_party_id" uuid NOT NULL REFERENCES "partners"("id"),"settlement_party_name" varchar(200) NOT NULL,"currency" varchar(3) NOT NULL,"amount" numeric(28,8) NOT NULL,"verification_date" varchar(10) NOT NULL,"note" varchar(500),"version" bigint NOT NULL DEFAULT 1,"reversed_at" timestamptz,"reversed_by" uuid REFERENCES "users"("id"),"reversal_reason" varchar(500),CONSTRAINT "verification_status_check" CHECK("status" IN('ACTIVE','REVERSED')),CONSTRAINT "verification_direction_check" CHECK("direction" IN('RECEIVABLE','PAYABLE')),CONSTRAINT "verification_amount_positive" CHECK("amount">0),CONSTRAINT "verification_reverse_consistency" CHECK(("status"='ACTIVE' AND "reversed_at" IS NULL AND "reversed_by" IS NULL AND "reversal_reason" IS NULL) OR ("status"='REVERSED' AND "reversed_at" IS NOT NULL AND "reversed_by" IS NOT NULL AND "reversal_reason" IS NOT NULL)));
CREATE TABLE "finance_verification_allocations"("id" uuid PRIMARY KEY,"created_at" timestamptz NOT NULL,"updated_at" timestamptz NOT NULL,"verification_id" uuid NOT NULL REFERENCES "finance_verifications"("id"),"cashflow_id" uuid NOT NULL REFERENCES "finance_cashflows"("id"),"bill_id" uuid NOT NULL REFERENCES "finance_bills"("id"),"cashflow_no" varchar(64) NOT NULL,"bill_no" varchar(64) NOT NULL,"amount" numeric(28,8) NOT NULL,"active" boolean NOT NULL DEFAULT true,CONSTRAINT "verification_allocation_amount_positive" CHECK("amount">0));
CREATE UNIQUE INDEX "financeverification_org_no" ON "finance_verifications"("organization_id","verification_no");CREATE UNIQUE INDEX "financeverification_org_idempotency" ON "finance_verifications"("organization_id","idempotency_key");CREATE INDEX "financeverification_org_status_date" ON "finance_verifications"("organization_id","status","verification_date");CREATE INDEX "verification_allocation_verification" ON "finance_verification_allocations"("verification_id","active");CREATE INDEX "verification_allocation_cashflow" ON "finance_verification_allocations"("cashflow_id","active");CREATE INDEX "verification_allocation_bill" ON "finance_verification_allocations"("bill_id","active");
